#include <stdio.h>
#include <stdlib.h>

int counter = 0;                     // static storage duration

int main(void) {
    int local = 5;                   // automatic: on the stack
    int *heap = malloc(sizeof(int)); // allocated: on the heap
    *heap = 7;

    printf("&counter = %p (static)\n", (void *) &counter);
    printf("heap     = %p (heap)\n", (void *) heap);
    printf("&local   = %p (stack)\n", (void *) &local);
    printf("&heap    = %p (stack: the pointer variable itself)\n", (void *) &heap);

    free(heap);
    return 0;
}

#include <stdio.h>
