#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s n\n", argv[0]);
        return 1;
    }
    size_t n = atoi(argv[1]);
    if (n == 0) {
        fprintf(stderr, "n must be at least 1\n");
        return 1;
    }

    int *sq = malloc(n * sizeof(int));        // room for n ints
    if (!sq) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (size_t i = 0; i < n; i++) {
        sq[i] = (int) (i * i);                // use it like any array
    }
    for (size_t i = 0; i < n; i++) {
        printf("%d ", sq[i]);
    }
    printf("\n");

    double *half = malloc(n * sizeof(double)); // room for n doubles
    if (!half) {
        free(sq);
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (size_t i = 0; i < n; i++) {
        half[i] = sq[i] / 2.0;
    }
    printf("half[n - 1] = %.1f\n", half[n - 1]);

    free(sq);
    free(half);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Returns a pointer to the first element of a new array holding
// n, n - 1, ..., 1. The caller must free it. Returns NULL if out of memory.
int *countdown(size_t n) {
    int *arr = malloc(n * sizeof(int));   // lifetime starts here...
    if (!arr) {
        return NULL;
    }
    for (size_t i = 0; i < n; i++) {
        arr[i] = (int) (n - i);
    }
    return arr;                           // ...and does NOT end here
}

int main(void) {
    int *a = countdown(5);
    if (!a) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (size_t i = 0; i < 5; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
    free(a);                              // lifetime ends here
    return 0;
}

