int *countdown3(void) {
    int arr[3] = {3, 2, 1};   // automatic: dies when the function returns
    return arr;               // WRONG: address of a local array
}

int main(void) {
    int *a = countdown3();
    printf("%d\n", a[0]);     // undefined behaviour
    return 0;
}

