    unsigned int *count = calloc(n, sizeof(unsigned int));  // n zeros
    if (!count) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    int rolls[] = {2, 5, 2, 0, 5, 5, 3};
    for (size_t i = 0; i < 7; i++) {
