        printf("%zu: %u\n", i, count[i]);
    }
    free(count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Returns the sum 1 + 2 + ... + n, using a heap array (to show a leak)
int total(int n) {
    int *a = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        a[i] = i + 1;
    }
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
    }
    return sum;            // BUG: a is never freed
}

int main(void) {
    for (int k = 1; k <= 3; k++) {
        printf("total(%d) = %d\n", 10 * k, total(10 * k));
    }
    return 0;
}

