#include <stdio.h>
#include <stdlib.h>

// Returns a new array holding lo, lo + 1, ..., hi (requires lo <= hi).
// Its length is hi - lo + 1. The caller must free it. NULL if out of memory.
int *range(int lo, int hi) {
    size_t n = hi - lo + 1;
    int *arr = malloc(n * sizeof(int));
    if (!arr) {
        return NULL;
    }
    for (size_t i = 0; i < n; i++) {
        arr[i] = lo + (int) i;
    }
    return arr;
}

int main(void) {
    int *r = range(3, 7);
    if (!r) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (size_t i = 0; i < 5; i++) {
        printf("%d ", r[i]);
    }
    printf("\n");
    free(r);
    return 0;
}

