#include <stdio.h>
#include <stdlib.h>

// Returns a new array of 10 counts: element d is how many times the
// digit character d appears in s. The caller must free it. NULL if out of memory.
size_t *digit_counts(char s[]) {
    size_t *counts = calloc(10, sizeof(size_t));
    if (!counts) {
        return NULL;
    }
    for (size_t i = 0; s[i] != '\0'; i++) {
        if (s[i] >= '0' && s[i] <= '9') {
            counts[s[i] - '0']++;
        }
    }
    return counts;
}

int main(void) {
    size_t *c = digit_counts("2026-11-18");
    if (!c) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (int d = 0; d < 10; d++) {
        if (c[d] > 0) {
            printf("%d: %zu\n", d, c[d]);
        }
    }
    free(c);
    return 0;
}

write.prompt:
Write a `main` (with the `#include`s it needs) that shows how to:

(a) use `malloc` to allocate memory for a single `long` value and store 123456789 in it;

(b) use `malloc` to allocate memory for an array of 25 `short` values and store 1, 2, ..., 25 in it;

(c) use `calloc` to allocate memory for an array of 40 `double` values that are all 0.0, without writing a loop;

(d) release all of the memory.

Check every allocation for failure (print a message to standard error and exit with `EXIT_FAILURE`). You may print a few values to test it.

write.solution:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    // (a) one long
    long *big = malloc(sizeof(long));
    if (!big) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    *big = 123456789L;

    // (b) an array of 25 short values, set to 1, 2, ..., 25
    short *s = malloc(25 * sizeof(short));
    if (!s) {
        free(big);
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < 25; i++) {
        s[i] = i + 1;
    }

    // (c) an array of 40 double values, all 0.0, without a loop
    double *d = calloc(40, sizeof(double));
    if (!d) {
        free(big);
        free(s);
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }

    printf("%ld %d %d %.1f\n", *big, s[0], s[24], d[39]);

    // (d) release everything
    free(big);
    free(s);
    free(d);
    return 0;
}
